CREATE TABLE IF NOT EXISTS shareholders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legal_name text NOT NULL, shareholder_type text NOT NULL, share_class text NOT NULL, shares numeric(30,6) NOT NULL DEFAULT 0, voting_rights numeric(30,6) NOT NULL DEFAULT 0, beneficial_owner text, protected_interest boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS board_directors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, role_name text NOT NULL, independent boolean NOT NULL DEFAULT false, appointment_date date, term_end_date date, skills text, committee_memberships text, conflict_status text NOT NULL DEFAULT 'Declared / Review Required', status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resolution_number text NOT NULL UNIQUE, resolution_type text NOT NULL, title text NOT NULL, proposed_by text, approval_level text NOT NULL, status text NOT NULL DEFAULT 'Draft', meeting_date date, decision_date date, vote_for numeric DEFAULT 0, vote_against numeric DEFAULT 0, abstain numeric DEFAULT 0, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conflict_declarations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_name text NOT NULL, role_name text, related_party text, matter text NOT NULL, disclosure text NOT NULL, recusal_required boolean NOT NULL DEFAULT false, review_status text NOT NULL DEFAULT 'Open', reviewed_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS authority_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category text NOT NULL, action text NOT NULL, approval_level text NOT NULL, threshold_amount numeric(14,2), currency text DEFAULT 'NGN', notes text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
