INSERT INTO authority_rules(category,action,approval_level,currency,notes,active) SELECT 'Operations','Ordinary operating expenditure','Delegated executive authority','NGN','Within approved annual budget and management delegation.',true WHERE NOT EXISTS (SELECT 1 FROM authority_rules WHERE action='Ordinary operating expenditure');
INSERT INTO authority_rules(category,action,approval_level,currency,notes,active) SELECT 'Capital','Material capital expenditure','Board / Investment & Capital Committee','NGN','Above management delegation or outside approved capital plan.',true WHERE NOT EXISTS (SELECT 1 FROM authority_rules WHERE action='Material capital expenditure');
INSERT INTO authority_rules(category,action,approval_level,notes,active) SELECT 'Assets','Strategic asset disposal','Board + applicable shareholder approval','Material sale, transfer or encumbrance of strategic assets.',true WHERE NOT EXISTS (SELECT 1 FROM authority_rules WHERE action='Strategic asset disposal');
INSERT INTO authority_rules(category,action,approval_level,notes,active) SELECT 'Integrity','Related-party transaction','Independent review + Board approval','Material transaction involving connected persons.',true WHERE NOT EXISTS (SELECT 1 FROM authority_rules WHERE action='Related-party transaction');
INSERT INTO authority_rules(category,action,approval_level,notes,active) SELECT 'Stewardship','Indigenous/community rights-impacting transaction','Stewardship Committee + Board','Material impact on legitimate indigenous, customary or community interests.',true WHERE NOT EXISTS (SELECT 1 FROM authority_rules WHERE action='Indigenous/community rights-impacting transaction');
INSERT INTO authority_rules(category,action,approval_level,notes,active) SELECT 'Expansion','New country entry','Board + local legal review','New African jurisdiction or regulated operating activity.',true WHERE NOT EXISTS (SELECT 1 FROM authority_rules WHERE action='New country entry');